patch:
diff --git a/demos/low-latency-llama/rms_matvec_rope_append.cu b/demos/low-latency-llama/rms_matvec_rope_append.cu
index f7af6c6..e9b6276 100644
--- a/demos/low-latency-llama/rms_matvec_rope_append.cu
+++ b/demos/low-latency-llama/rms_matvec_rope_append.cu
@@ -117,9 +117,17 @@ template <typename Config, typename Globals> struct rms_qkv_rope_append {
                 // Compute RoPE in-place
                 if (kittens::laneid() < 16) {
                     // will clean this up later
-                    qkv_proj[0][0] =
-                        float(qkv_proj[0][0]) * rope_cos[0][0] +
-                        float(-1 * mod) * float(pair_val) * rope_sin[0][0];
+                    if constexpr (Config::MATCH_TORCH_BF16_EPILOGUES) {
+                        // Eager reference RoPE computes two FP32 products then
+                        // adds them. Prevent contraction across that boundary.
+                        const float direct = __fmul_rn(float(qkv_proj[0][0]), rope_cos[0][0]);
+                        const float rotated = __fmul_rn(float(-mod) * pair_val, rope_sin[0][0]);
+                        qkv_proj[0][0] = __fadd_rn(direct, rotated);
+                    } else {
+                        qkv_proj[0][0] =
+                            float(qkv_proj[0][0]) * rope_cos[0][0] +
+                            float(-1 * mod) * float(pair_val) * rope_sin[0][0];
+                    }
                 }
             }
